// ── Storage ───────────────────────────────────────────────────────────────────

// Substituted at build time by webpack DefinePlugin — not a real Node runtime lookup.
declare const process: { env: { TMDB_API_KEY?: string } };

const KEY_APIKEY = 'atlantis:movies:apikey';
const ENV_API_KEY = process.env.TMDB_API_KEY ?? '';

function loadApiKey(runtimeApiKey?: string): string | null {
  if (runtimeApiKey) return runtimeApiKey;
  if (ENV_API_KEY) return ENV_API_KEY;
  try { return localStorage.getItem(KEY_APIKEY); } catch { return null; }
}
function saveApiKey(k: string): void {
  try { localStorage.setItem(KEY_APIKEY, k); } catch {}
}

