// ── Row type ──────────────────────────────────────────────────────────────────

interface Row { title: string; items: MediaItem[]; loading: boolean }

// ── Smart suggestions ─────────────────────────────────────────────────────────

function getTopGenres(items: MediaItem[], topN = 2): number[] {
  const count: Record<number, number> = {};
  for (const item of items) {
    for (const g of item.genre_ids ?? []) {
      count[g] = (count[g] ?? 0) + 1;
    }
  }
  return Object.entries(count)
    .sort((a, b) => Number(b[1]) - Number(a[1]))
    .slice(0, topN)
    .map(([id]) => Number(id));
}

// ── App ───────────────────────────────────────────────────────────────────────

interface AppProps { topBarRight?: React.ReactNode; apiKey?: string }

const EMPTY_FILTERS: DiscoverFilters = { genres: [], providerIds: [], decades: [] };

export default function App({ topBarRight, apiKey: runtimeApiKey }: AppProps) {
  const [apiKey, setApiKey] = useState<string | null>(() => loadApiKey(runtimeApiKey));
  const [activeTab,    setActiveTab]    = useState<TabId>('discover');
  const [filters,      setFilters]      = useState<DiscoverFilters>(EMPTY_FILTERS);
  const [showFilter,   setShowFilter]   = useState(false);
  const [rows,         setRows]         = useState<Row[]>([]);
  const [heroItems,    setHeroItems]    = useState<MediaItem[]>([]);
  const [heroIdx,      setHeroIdx]      = useState(0);
  const [selectedItem, setSelectedItem] = useState<MediaItem | null>(null);

  // Browser back button support for detail view
  const selectItem = useCallback((item: MediaItem | null) => {
    if (item) {
      history.pushState({ movieDetail: true }, '');
    }
    setSelectedItem(item);
  }, []);

  useEffect(() => {
    const onPopState = () => {
      if (selectedItem) {
        setSelectedItem(null);
      }
    };
    window.addEventListener('popstate', onPopState);
    return () => window.removeEventListener('popstate', onPopState);
  }, [selectedItem]);
  const [libraryVersion, setLibraryVersion] = useState(0);
  const [searchQuery,  setSearchQuery]  = useState('');
  const [searchResults, setSearchResults] = useState<MediaItem[]>([]);
  const [searchLoading, setSearchLoading] = useState(false);
  const searchTimer = useRef<ReturnType<typeof setTimeout>>();
  const heroTimer   = useRef<ReturnType<typeof setTimeout>>();

  const onLibraryChange = useCallback(() => setLibraryVersion((v) => v + 1), []);

  useEffect(() => { setApiKey(loadApiKey(runtimeApiKey)); }, [runtimeApiKey]);

  // ── Hero auto-advance ──────────────────────────────────────────────────────

  useEffect(() => {
    if (heroItems.length < 2) return;
    heroTimer.current = setInterval(() => {
      setHeroIdx((i) => (i + 1) % heroItems.length);
    }, 7000);
    return () => clearInterval(heroTimer.current);
  }, [heroItems.length]);

  // ── Search ─────────────────────────────────────────────────────────────────

  useEffect(() => {
    if (!apiKey) return;
    clearTimeout(searchTimer.current);
    if (!searchQuery.trim()) { setSearchResults([]); return; }
    setSearchLoading(true);
    searchTimer.current = setTimeout(async () => {
      try {
        const r = await search(apiKey, searchQuery.trim());
        setSearchResults(r);
      } catch { setSearchResults([]); }
      finally { setSearchLoading(false); }
    }, 380);
  }, [apiKey, searchQuery]);

  // ── Load content ───────────────────────────────────────────────────────────

  const hasFilters = filters.genres.length > 0 || filters.providerIds.length > 0 || filters.decades.length > 0;

  const loadContent = useCallback(async (key: string, tab: TabId, f: DiscoverFilters) => {
    // Library tabs — no API call
    if (tab === 'favorites') {
      const items = loadFavorites();
      setRows([{ title: 'My Favorites', items, loading: false }]);
      return;
    }
    if (tab === 'seen') {
      const items = loadSeen();
      setRows([{ title: 'Recently Seen', items, loading: false }]);
      return;
    }

    const active = f.genres.length > 0 || f.providerIds.length > 0 || f.decades.length > 0;

    // If filters active, show results grouped by genre category
    if (active) {
      const mediaType = tab === 'movies' ? 'movie' : tab === 'tv' ? 'tv' : tab === 'documentaries' ? 'movie' : 'all';
      const genresWithDoc = tab === 'documentaries' ? [...f.genres, 99] : f.genres;

      // If specific genres selected, fetch each genre separately for categorized rows
      const genreIds = genresWithDoc.length > 0
        ? genresWithDoc
        : [28, 35, 18, 878, 27, 10749, 53, 16]; // default: popular genres

      // Show loading skeletons
      const loadingRows = genreIds.map((g) => ({
        title: GENRE_MAP[g] ?? 'Other',
        items: [] as MediaItem[],
        loading: true,
      }));
      setRows(loadingRows);

      // Fetch each genre in parallel
      const results = await Promise.all(
        genreIds.map((g) =>
          discoverFiltered(key, mediaType as 'movie' | 'tv' | 'all', {
            ...f,
            genres: [g],
          }),
        ),
      );

      // Build rows, skipping empty genres
      const filledRows = genreIds
        .map((g, i) => ({
          title: GENRE_MAP[g] ?? 'Other',
          items: results[i] ?? [],
          loading: false,
        }))
        .filter((r) => r.items.length > 0);

      setRows(filledRows.length > 0 ? filledRows : [{ title: 'No Results', items: [], loading: false }]);
      return;
    }

    if (tab === 'documentaries') {
      setRows([{ title: 'Documentaries', items: [], loading: true }]);
      const docs = await getDocumentaries(key);
      setRows([{ title: 'Documentaries', items: docs, loading: false }]);
      return;
    }

    if (tab === 'movies') {
      setRows([
        { title: 'Popular Movies',    items: [], loading: true },
        { title: 'Top Rated Movies',  items: [], loading: true },
      ]);
      const [pop, top] = await Promise.all([
        getPopularMovies(key), getTopRated(key, 'movie'),
      ]);
      setRows([
        { title: 'Popular Movies',   items: pop, loading: false },
        { title: 'Top Rated Movies', items: top, loading: false },
      ]);
      return;
    }

    if (tab === 'tv') {
      setRows([
        { title: 'Popular TV Shows',   items: [], loading: true },
        { title: 'Top Rated TV Shows', items: [], loading: true },
      ]);
      const [pop, top] = await Promise.all([
        getPopularTv(key), getTopRated(key, 'tv'),
      ]);
      setRows([
        { title: 'Popular TV Shows',   items: pop, loading: false },
        { title: 'Top Rated TV Shows', items: top, loading: false },
      ]);
      return;
    }

    // ── Discover ──────────────────────────────────────────────────────────
    const libraryItems = [...loadFavorites(), ...loadSeen()];
    const topGenres    = getTopGenres(libraryItems, 2);

    const rowDefs: { title: string; loading: boolean; items: MediaItem[] }[] = [
      { title: 'Trending This Week', loading: true, items: [] },
      { title: 'Popular Movies',     loading: true, items: [] },
      { title: 'Popular TV Shows',   loading: true, items: [] },
      { title: 'Top Rated Movies',   loading: true, items: [] },
      { title: 'Documentaries',      loading: true, items: [] },
      ...topGenres.map((g) => ({
        title: `More ${GENRE_MAP[g] ?? 'Great'} Content`,
        loading: true,
        items: [],
      })),
    ];
    setRows(rowDefs);

    const [trending, movies, tv, topMovies, docs, ...genreRows] = await Promise.all([
      getTrending(key),
      getPopularMovies(key),
      getPopularTv(key),
      getTopRated(key, 'movie'),
      getDocumentaries(key),
      ...topGenres.map((g) =>
        discoverFiltered(key, 'all', { genres: [g], providerIds: [], decades: [] }),
      ),
    ]);

    // First 5 with backdrops → carousel
    const carouselItems = trending.filter((i) => i.backdrop_path).slice(0, 5);
    setHeroItems(carouselItems);
    setHeroIdx(0);

    setRows([
      { title: 'Trending This Week', items: trending, loading: false },
      { title: 'Popular Movies',     items: movies,   loading: false },
      { title: 'Popular TV Shows',   items: tv,       loading: false },
      { title: 'Top Rated Movies',   items: topMovies, loading: false },
      { title: 'Documentaries',      items: docs,     loading: false },
      ...topGenres.map((g, i) => ({
        title: `More ${GENRE_MAP[g] ?? 'Great'} Content`,
        items: genreRows[i] ?? [],
        loading: false,
      })),
    ]);
  }, []);

  useEffect(() => {
    if (!apiKey) return;
    if (activeTab !== 'discover') setHeroItems([]);
    loadContent(apiKey, activeTab, filters).catch(() => {});
  }, [apiKey, activeTab, filters, loadContent, libraryVersion]);

  // ── Helpers ────────────────────────────────────────────────────────────────

  const handleTabChange = useCallback((id: TabId) => {
    setActiveTab(id);
    setSearchQuery('');
  }, []);

  const handleFiltersChange = useCallback((f: DiscoverFilters) => {
    setFilters(f);
  }, []);

  const isSearching   = searchQuery.trim().length > 0;
  const heroItem      = heroItems[heroIdx] ?? null;
  const isLibraryEmpty =
    (activeTab === 'favorites' || activeTab === 'seen') &&
    !rows[0]?.loading && rows[0]?.items.length === 0;

  const filterCount = filters.genres.length + filters.providerIds.length + filters.decades.length;

  // ── Render ─────────────────────────────────────────────────────────────────

  if (!apiKey) return <ApiKeySetup onSave={(k) => { saveApiKey(k); setApiKey(k); }} />;

  const searchBar = (
    <SearchBarWrap>
      <Search size={14} color={theme.colors.mainTextMuted} />
      <SearchInput
        placeholder="Search…"
        value={searchQuery}
        onChange={(e) => setSearchQuery(e.target.value)}
      />
      {searchQuery && (
        <ClearBtn onClick={() => setSearchQuery('')} aria-label="Clear">
          <X size={13} />
        </ClearBtn>
      )}
    </SearchBarWrap>
  );

  if (selectedItem) {
    const detailTopBar = (
      <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
        <button
          onClick={() => history.back()}
          title="Back"
          style={{
            display: 'flex', alignItems: 'center', gap: 6,
            padding: '5px 14px', background: 'none',
            border: `1px solid ${theme.colors.border}`, borderRadius: theme.borderRadius.md,
            color: theme.colors.sidebarTextMuted, cursor: 'pointer',
            fontSize: theme.typography.fontSizeSm, fontFamily: theme.typography.fontFamily,
            fontWeight: 500, transition: 'color 0.15s, border-color 0.15s',
          }}
          onMouseEnter={(e) => { e.currentTarget.style.color = theme.colors.mainText; e.currentTarget.style.borderColor = theme.colors.mainText; }}
          onMouseLeave={(e) => { e.currentTarget.style.color = theme.colors.sidebarTextMuted; e.currentTarget.style.borderColor = theme.colors.border; }}
        >
          <ArrowLeft size={14} /> Back
        </button>
        {topBarRight}
      </div>
    );

    return (
      <Layout
        title={mediaTitle(selectedItem)}
        sidebar={null}
        topBarRight={detailTopBar}
      >
        <DetailPage
          item={selectedItem}
          apiKey={apiKey}
          onBack={() => history.back()}
          onLibraryChange={onLibraryChange}
          onSelect={selectItem}
        />
      </Layout>
    );
  }

  return (
    <>
      <Layout
        title="Movies & Series"
        sidebar={null}
        topBarRight={<>{searchBar}{topBarRight}</>}
      >
        <MainScroll>
          {/* ── Tab bar ── */}
          <TabBar>
            {TABS.map(({ id, label, Icon }) => (
              <TabBtn
                key={id}
                active={activeTab === id}
                onClick={() => handleTabChange(id)}
              >
                <Icon size={14} />
                {label}
              </TabBtn>
            ))}
            <FilterBtnWrap>
              <FilterBtn
                hasFilters={filterCount > 0}
                onClick={() => setShowFilter(true)}
              >
                <SlidersHorizontal size={13} />
                Filter
                {filterCount > 0 && <FilterCount>{filterCount}</FilterCount>}
              </FilterBtn>
            </FilterBtnWrap>
          </TabBar>

          {/* ── Content ── */}
          {isSearching ? (
            <ContentArea>
              <PageHeader>
                <PageTitle>
                  {searchLoading
                    ? 'Searching…'
                    : searchResults.length > 0
                    ? `Results for "${searchQuery}"`
                    : `No results for "${searchQuery}"`}
                </PageTitle>
              </PageHeader>
              {!searchLoading && searchResults.length === 0 ? (
                <EmptyState>
                  <span style={{ fontSize: 44 }}>🔍</span>
                  Nothing found — try a different title
                </EmptyState>
              ) : (
                <ContentRow title="" items={searchResults} loading={searchLoading} onSelect={selectItem} />
              )}
            </ContentArea>
          ) : (
            <ContentArea key={activeTab}>
              {/* Hero carousel — Discover only, no active filters */}
              {activeTab === 'discover' && heroItem && !hasFilters && (
                <HeroSection>
                  {heroItems.map((item, i) => {
                    const backdrop = item.backdrop_path
                      ? `https://image.tmdb.org/t/p/w1280${item.backdrop_path}`
                      : '';
                    return (
                      <HeroSlide key={item.id} src={backdrop} active={i === heroIdx}>
                        <HeroContent>
                          <HeroTag kind={item.media_type}>
                            {item.media_type === 'movie' ? 'Film' : 'TV Show'}
                          </HeroTag>
                          <HeroTitle>{mediaTitle(item)}</HeroTitle>
                          <HeroMeta>
                            <HeroRating>
                              ★ {item.vote_average.toFixed(1)}
                            </HeroRating>
                            {(item.release_date || item.first_air_date) && (
                              <HeroYear>
                                {(item.release_date ?? item.first_air_date ?? '').slice(0, 4)}
                              </HeroYear>
                            )}
                          </HeroMeta>
                          {item.overview && (
                            <HeroOverview>{item.overview}</HeroOverview>
                          )}
                          <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                            <HeroCTA onClick={() => selectItem(item)}>
                              ▶ More Info
                            </HeroCTA>
                            <HeroDots>
                              {heroItems.map((_, di) => (
                                <HeroDot
                                  key={di}
                                  active={di === heroIdx}
                                  onClick={() => { clearInterval(heroTimer.current); setHeroIdx(di); }}
                                />
                              ))}
                            </HeroDots>
                          </div>
                        </HeroContent>
                      </HeroSlide>
                    );
                  })}
                </HeroSection>
              )}

              {/* Filter pills summary */}
              {hasFilters && (
                <FilterTag>
                  <span style={{ fontSize: 12, color: theme.colors.mainTextMuted }}>Active filters:</span>
                  {filters.genres.map((g) => (
                    <FilterPill key={g}>{GENRE_MAP[g] ?? g}</FilterPill>
                  ))}
                  {filters.providerIds.map((id) => (
                    <FilterPill key={id}>
                      {STREAMING_PROVIDERS.find((p) => p.id === id)?.name ?? id}
                    </FilterPill>
                  ))}
                  {filters.decades.map((d) => (
                    <FilterPill key={d}>{d}</FilterPill>
                  ))}
                  <button
                    style={{
                      background: 'none', border: 'none', color: theme.colors.mainTextMuted,
                      fontSize: 11, cursor: 'pointer', textDecoration: 'underline',
                    }}
                    onClick={() => setFilters(EMPTY_FILTERS)}
                  >
                    Clear all
                  </button>
                </FilterTag>
              )}

              {/* Page header for non-discover tabs */}
              {activeTab !== 'discover' && (
                <PageHeader>
                  <PageTitle>
                    {TABS.find((t) => t.id === activeTab)?.label ?? ''}
                  </PageTitle>
                </PageHeader>
              )}

              {/* Content rows */}
              {isLibraryEmpty ? (
                <EmptyState>
                  <span style={{ fontSize: 44 }}>
                    {activeTab === 'favorites' ? '❤️' : '👁️'}
                  </span>
                  {activeTab === 'favorites'
                    ? 'No favorites yet — open any title and hit ❤️'
                    : 'No seen titles yet — mark a title as seen to track it here'}
                </EmptyState>
              ) : (
                rows.map((row) => (
                  <ContentRow
                    key={row.title}
                    title={row.title}
                    items={row.items}
                    loading={row.loading}
                    onSelect={selectItem}
                  />
                ))
              )}
            </ContentArea>
          )}
        </MainScroll>
      </Layout>

      {/* Filter modal */}
      {showFilter && (
        <FilterModal
          filters={filters}
          onChange={handleFiltersChange}
          onClose={() => setShowFilter(false)}
        />
      )}

    </>
  );
}
